CREATE OR REPLACE PROCEDURE public.sp_update_weekly_planning_draft_item(IN p_id uuid, IN p_tenant_id uuid, IN p_scheduled_date date, IN p_day_of_week character varying, IN p_time_of_day character varying, IN p_experience_id uuid, IN p_experience_title character varying, IN p_learning_goal text, IN p_group_format character varying, IN p_estimated_duration_minutes integer, IN p_required_materials text, IN p_rationale text, IN p_validation_status character varying, IN p_validation_notes text, IN p_resulting_schedule_id uuid)  LANGUAGE plpgsql AS $procedure$ BEGIN     UPDATE weekly_planning_draft_items SET         scheduled_date = p_scheduled_date,         day_of_week = p_day_of_week,         time_of_day = p_time_of_day,         experience_id = p_experience_id,         experience_title = p_experience_title,         learning_goal = p_learning_goal,         group_format = p_group_format,         estimated_duration_minutes = p_estimated_duration_minutes,         required_materials = p_required_materials,         rationale = p_rationale,         validation_status = p_validation_status,         validation_notes = p_validation_notes,         resulting_schedule_id = p_resulting_schedule_id     WHERE id = p_id AND tenant_id = p_tenant_id; END; $procedure$ ;
